"""Generated by scripts/sync-email-theme.py; keep light-mode inline fallbacks."""
import re

CSS = ':root { color-scheme: light dark; supported-color-schemes: light dark; }\n@media (prefers-color-scheme: dark) {\n  .ts-bg-outer { background-color: #151B17 !important; }\n  .ts-bg-surface { background-color: #202621 !important; }\n  .ts-bg-footer { background-color: #202621 !important; }\n  .ts-bg-danger { background-color: #402723 !important; }\n  .ts-bg-success { background-color: #213B2B !important; }\n  .ts-bg-warning { background-color: #40351F !important; }\n  .ts-bg-info { background-color: #26343C !important; }\n  .ts-fg { color: #EEE9DE !important; }\n  .ts-primary { color: #F4EFE6 !important; }\n  .ts-muted { color: #C3C5B8 !important; }\n  .ts-danger { color: #FFB4A9 !important; }\n  .ts-success { color: #A2D7AE !important; }\n  .ts-warning { color: #F0CE83 !important; }\n  .ts-info { color: #BFCDD7 !important; }\n  .ts-border { border-color: #465047 !important; }\n  .ts-art-light { display: none !important; max-height: 0 !important; overflow: hidden !important; }\n  .ts-art-dark { display: block !important; max-height: none !important; overflow: hidden !important; height: auto !important; }\n}\n[data-ogsc] .ts-bg-outer { background-color: #151B17 !important; }\n[data-ogsc] .ts-bg-surface { background-color: #202621 !important; }\n[data-ogsc] .ts-bg-footer { background-color: #202621 !important; }\n[data-ogsc] .ts-bg-danger { background-color: #402723 !important; }\n[data-ogsc] .ts-bg-success { background-color: #213B2B !important; }\n[data-ogsc] .ts-bg-warning { background-color: #40351F !important; }\n[data-ogsc] .ts-bg-info { background-color: #26343C !important; }\n[data-ogsc] .ts-fg { color: #EEE9DE !important; }\n[data-ogsc] .ts-primary { color: #F4EFE6 !important; }\n[data-ogsc] .ts-muted { color: #C3C5B8 !important; }\n[data-ogsc] .ts-danger { color: #FFB4A9 !important; }\n[data-ogsc] .ts-success { color: #A2D7AE !important; }\n[data-ogsc] .ts-warning { color: #F0CE83 !important; }\n[data-ogsc] .ts-info { color: #BFCDD7 !important; }\n[data-ogsc] .ts-border { border-color: #465047 !important; }\n[data-ogsc] .ts-art-light { display: none !important; max-height: 0 !important; overflow: hidden !important; }\n[data-ogsc] .ts-art-dark { display: block !important; max-height: none !important; overflow: hidden !important; height: auto !important; }\n'
RULES = {'background-color': {'#f4efe6': ['ts-bg-outer', '#151B17'], '#ffffff': ['ts-bg-surface', '#202621'], '#fdfbf6': ['ts-bg-footer', '#202621'], '#fbe9e7': ['ts-bg-danger', '#402723'], '#e2f3e3': ['ts-bg-success', '#213B2B'], '#fbf1df': ['ts-bg-warning', '#40351F'], '#eef1f4': ['ts-bg-info', '#26343C']}, 'color': {'#3d4045': ['ts-fg', '#EEE9DE'], '#6b2a22': ['ts-primary', '#F4EFE6'], '#655d54': ['ts-muted', '#C3C5B8'], '#b42318': ['ts-danger', '#FFB4A9'], '#2f7f33': ['ts-success', '#A2D7AE'], '#b7791f': ['ts-warning', '#F0CE83'], '#5b6b7a': ['ts-info', '#BFCDD7']}}
ARTWORK = {
    'email-header.png': 'email-header-dark.png',
    'email-footer-waves-compact.png': 'email-footer-waves-dark.png',
}


def _classes(tag):
    style = re.search(r'\bstyle="([^"]*)"', tag, re.I)
    if not style:
        return tag
    declarations = dict((key.strip().lower(), value.strip().lower())
                        for key, value in re.findall(r'([\w-]+)\s*:\s*([^;]+)', style.group(1)))
    classes = []
    for prop, values in RULES.items():
        value = declarations.get(prop)
        if value in values:
            classes.append(values[value][0])
    if any(key.startswith('border') and ('#e5dccf' in value or '#f4efe6' in value)
           for key, value in declarations.items()):
        classes.append('ts-border')
    if not classes:
        return tag
    existing = re.search(r'\bclass="([^"]*)"', tag, re.I)
    if existing:
        merged = list(dict.fromkeys(existing.group(1).split() + classes))
        return tag[:existing.start(1)] + ' '.join(merged) + tag[existing.end(1):]
    return re.sub(r'^(<[^\s>]+)', lambda m: m.group(1) + ' class="' + ' '.join(classes) + '"', tag)


def _artwork(tag):
    if not re.match(r'<img\b', tag, re.I):
        return tag
    for light, dark in ARTWORK.items():
        if '/' + light not in tag:
            continue
        light_tag = re.sub(r'\bclass="([^"]*)"', lambda m: 'class="' + m.group(1) + ' ts-art-light"', tag) if re.search(r'\bclass="', tag) else tag.replace('<img', '<img class="ts-art-light"', 1)
        dark_tag = tag.replace('/' + light, '/' + dark)
        dark_tag = re.sub(r'\bclass="([^"]*)"', lambda m: 'class="' + m.group(1) + ' ts-art-dark"', dark_tag) if re.search(r'\bclass="', dark_tag) else dark_tag.replace('<img', '<img class="ts-art-dark"', 1)
        dark_tag = dark_tag.replace('display:block;', 'display:none;').replace('display: block;', 'display:none;')
        dark_tag = dark_tag.replace('style="', 'style="max-height:0;overflow:hidden;mso-hide:all;', 1)
        return light_tag + dark_tag
    return tag


def apply_email_theme(html):
    """Add progressive dark-mode support; content and light inline styles stay intact."""
    if 'id="tsuru-email-theme"' in html:
        return html
    html = re.sub(r'(<meta\s+name="(?:color-scheme|supported-color-schemes)"\s+content=")light("\s*/?>)',
                  r'\1light dark\2', html, flags=re.I)
    html = re.sub(r'<[a-z][^>]*>', lambda m: _artwork(_classes(m.group(0))), html, flags=re.I)
    return html.replace('</head>', '<style id="tsuru-email-theme">\n' + CSS + '</style>\n</head>', 1)
